mapper.select:
SELECT * FROM( SELECT A.CUSTOMER_ID customerId, A.PFLSH PFLSH, Sum(A.CREDIT_AMT)/100000000 creditAmt, A.MDATE MDATE, C.CUSTOMER_NAME as customerName, A.CCY, CASE WHEN A.MDATE < #{ptDate,jdbcType=DATE} THEN '01' ELSE '02' END codeStatus FROM CREDIT_LINES A left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID=C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID=D.CUSTOMER_ID
A.CREDIT_TYPE='04'
AND A.CUSTOMER_ID in
#{item}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND to_char(A.VDATE,'yyyy-MM-dd') = #{vdate,jdbcType=DATE}
AND to_char(A.MDATE,'yyyy-MM-dd') = #{mdate,jdbcType=DATE}
AND A.CCY = #{ccy,jdbcType=VARCHAR}
GROUP BY A.CUSTOMER_ID,A.MDATE,A.CCY,A.PFLSH,C.CUSTOMER_NAME ) C
C.codeStatus= #{codeStatus,jdbcType=VARCHAR}

SELECT distinct C.CUSTOMER_NAME as customerName, A.CUSTOMER_ID customerId, A.CCY FROM CREDIT_LINES A left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID=C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID=D.CUSTOMER_ID
A.CREDIT_TYPE='04'
AND A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.CCY = #{ccy,jdbcType=VARCHAR}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND to_char(A.MDATE,'yyyy-MM-dd') = #{mdate,jdbcType=DATE}
group by A.CUSTOMER_ID,A.Mdate,A.CCY,A.Pflsh,C.CUSTOMER_NAME

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
         AND A.CREDIT_TYPE='04'

      and to_char(VDATE,'yyyy-MM-dd')<= #{vmdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')>=#{vmdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
          AND A.CREDIT_TYPE='04'

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES 
        where PFLSH = #{pflsh,jdbcType=VARCHAR}
          AND CREDIT_TYPE='04'

			 and  SEQNO <> #{seqno}


			and CREDIT_MST_ID=#{creditMstId}

SELECT distinct CUSTOMER_ID AS id, CUSTOMER_NAME AS text FROM MST_CUSTOMER_INFO where CUSTOMER_TYPE = #{customerType,jdbcType=VARCHAR}
AND (CUSTOMER_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) or CUSTOMER_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND CUSTOMER_ID = #{initValue,jdbcType=VARCHAR}

		SELECT count(1)
		FROM CREDIT_LINES A
		where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR}

        and A.PFLSH = #{pflsh,jdbcType=VARCHAR}
		and  A.Hap_Credit_Amt>0
